CREATE EXTENSION IF NOT EXISTS "citext";
CREATE EXTENSION IF NOT EXISTS "vector";

CREATE TYPE "PlatformRole" AS ENUM ('SUPER_ADMIN');
CREATE TYPE "UserStatus" AS ENUM ('ACTIVE', 'DISABLED');
CREATE TYPE "MembershipRole" AS ENUM ('CLIENT_ADMIN', 'CLIENT_STAFF');
CREATE TYPE "MembershipStatus" AS ENUM ('INVITED', 'ACTIVE', 'DISABLED');
CREATE TYPE "ClientStatus" AS ENUM ('ACTIVE', 'INACTIVE');
CREATE TYPE "EventStatus" AS ENUM ('DRAFT', 'READY', 'PUBLISHED', 'ARCHIVED');
CREATE TYPE "SourceType" AS ENUM ('DOCUMENT', 'USER_INPUT', 'CONCIERGE_UPDATE', 'SYSTEM');
CREATE TYPE "ProcessingStatus" AS ENUM ('PENDING', 'QUEUED', 'PROCESSING', 'COMPLETED', 'FAILED');
CREATE TYPE "InvitationStatus" AS ENUM ('PENDING', 'QUEUED', 'SENT', 'FAILED', 'REVOKED', 'ACCEPTED');
CREATE TYPE "InvitationType" AS ENUM ('PERSONALIZED', 'GENERAL');
CREATE TYPE "ConversationType" AS ENUM ('ORGANIZER', 'GUEST');
CREATE TYPE "MessageRole" AS ENUM ('USER', 'CONCIERGE', 'SYSTEM');
CREATE TYPE "MessageStatus" AS ENUM ('QUEUED', 'PROCESSING', 'STREAMING', 'COMPLETE', 'FAILED');
CREATE TYPE "JobStatus" AS ENUM ('PENDING', 'RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED');

CREATE TABLE "User" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "supabaseUserId" UUID NOT NULL UNIQUE, "email" CITEXT NOT NULL UNIQUE, "firstName" TEXT NOT NULL, "lastName" TEXT NOT NULL, "platformRole" "PlatformRole", "status" "UserStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "Client" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "name" TEXT NOT NULL, "slug" TEXT NOT NULL UNIQUE, "status" "ClientStatus" NOT NULL DEFAULT 'ACTIVE', "contactEmail" CITEXT, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "ClientMembership" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "clientId" UUID NOT NULL REFERENCES "Client"("id") ON DELETE CASCADE, "role" "MembershipRole" NOT NULL, "status" "MembershipStatus" NOT NULL DEFAULT 'INVITED', "invitedAt" TIMESTAMPTZ(3), "joinedAt" TIMESTAMPTZ(3), "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, UNIQUE("userId", "clientId"));
CREATE TABLE "ClientMembershipPermission" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "membershipId" UUID NOT NULL REFERENCES "ClientMembership"("id") ON DELETE CASCADE, "permission" TEXT NOT NULL, UNIQUE("membershipId", "permission"));
CREATE TABLE "Event" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "clientId" UUID NOT NULL REFERENCES "Client"("id") ON DELETE CASCADE, "createdByUserId" UUID NOT NULL REFERENCES "User"("id"), "name" TEXT NOT NULL, "slug" TEXT NOT NULL UNIQUE, "category" TEXT NOT NULL, "description" TEXT, "destination" TEXT, "venue" TEXT, "startAt" TIMESTAMPTZ(3), "endAt" TIMESTAMPTZ(3), "timezone" TEXT, "organizerName" TEXT, "organizerEmail" CITEXT, "status" "EventStatus" NOT NULL DEFAULT 'DRAFT', "configuration" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "EventFact" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "eventId" UUID NOT NULL REFERENCES "Event"("id") ON DELETE CASCADE, "key" TEXT NOT NULL, "value" TEXT NOT NULL, "valueType" TEXT NOT NULL DEFAULT 'text', "sourceType" "SourceType" NOT NULL, "sourceDocumentId" UUID, "sourcePage" INTEGER, "sourceSection" TEXT, "sourceUserId" UUID, "confidence" DECIMAL(4,3), "precedence" INTEGER NOT NULL DEFAULT 100, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, UNIQUE("eventId", "key"));
CREATE TABLE "EventLocation" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "eventId" UUID NOT NULL REFERENCES "Event"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "address" TEXT, "type" TEXT, "notes" TEXT, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "EventContact" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "eventId" UUID NOT NULL REFERENCES "Event"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "role" TEXT, "email" CITEXT, "phone" TEXT, "isEmergency" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "ScheduleItem" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "eventId" UUID NOT NULL REFERENCES "Event"("id") ON DELETE CASCADE, "title" TEXT NOT NULL, "description" TEXT, "startAt" TIMESTAMPTZ(3) NOT NULL, "endAt" TIMESTAMPTZ(3), "location" TEXT, "category" TEXT, "visibility" TEXT NOT NULL DEFAULT 'SHARED', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "Guest" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "eventId" UUID NOT NULL REFERENCES "Event"("id") ON DELETE CASCADE, "fullName" TEXT NOT NULL, "firstName" TEXT, "lastName" TEXT, "email" CITEXT NOT NULL, "normalizedEmail" TEXT NOT NULL, "company" TEXT, "jobTitle" TEXT, "phone" TEXT, "guestGroup" TEXT, "notesEncrypted" TEXT, "dietaryEncrypted" TEXT, "accessibilityEncrypted" TEXT, "accommodationEncrypted" TEXT, "travelEncrypted" TEXT, "metadata" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, UNIQUE("eventId", "normalizedEmail"));
CREATE TABLE "Invitation" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "eventId" UUID NOT NULL REFERENCES "Event"("id") ON DELETE CASCADE, "guestId" UUID REFERENCES "Guest"("id") ON DELETE CASCADE, "type" "InvitationType" NOT NULL DEFAULT 'PERSONALIZED', "tokenHash" TEXT UNIQUE, "tokenEncrypted" TEXT, "status" "InvitationStatus" NOT NULL DEFAULT 'PENDING', "expiresAt" TIMESTAMPTZ(3), "sentAt" TIMESTAMPTZ(3), "acceptedAt" TIMESTAMPTZ(3), "revokedAt" TIMESTAMPTZ(3), "failureCode" TEXT, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "GuestSession" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "guestId" UUID NOT NULL REFERENCES "Guest"("id") ON DELETE CASCADE, "eventId" UUID NOT NULL REFERENCES "Event"("id") ON DELETE CASCADE, "tokenHash" TEXT NOT NULL UNIQUE, "expiresAt" TIMESTAMPTZ(3) NOT NULL, "revokedAt" TIMESTAMPTZ(3), "lastUsedAt" TIMESTAMPTZ(3), "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Document" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "clientId" UUID NOT NULL, "eventId" UUID NOT NULL REFERENCES "Event"("id") ON DELETE CASCADE, "uploadedByUserId" UUID NOT NULL REFERENCES "User"("id"), "originalName" TEXT NOT NULL, "objectKey" TEXT NOT NULL UNIQUE, "bucket" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "size" INTEGER NOT NULL, "checksum" TEXT NOT NULL, "processingStatus" "ProcessingStatus" NOT NULL DEFAULT 'PENDING', "processingError" TEXT, "parserVersion" TEXT, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, UNIQUE("eventId", "checksum"));
ALTER TABLE "EventFact" ADD CONSTRAINT "EventFact_sourceDocumentId_fkey" FOREIGN KEY ("sourceDocumentId") REFERENCES "Document"("id") ON DELETE SET NULL;
CREATE TABLE "DocumentExtraction" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "documentId" UUID NOT NULL UNIQUE REFERENCES "Document"("id") ON DELETE CASCADE, "extractedText" TEXT NOT NULL, "parserVersion" TEXT NOT NULL, "extractionMetadata" JSONB NOT NULL DEFAULT '{}', "processedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "DocumentChunk" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "clientId" UUID NOT NULL, "eventId" UUID NOT NULL REFERENCES "Event"("id") ON DELETE CASCADE, "documentId" UUID NOT NULL REFERENCES "Document"("id") ON DELETE CASCADE, "content" TEXT NOT NULL, "embedding" vector(1536), "pageNumber" INTEGER, "section" TEXT, "metadata" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "KnowledgeEntry" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "clientId" UUID NOT NULL, "eventId" UUID NOT NULL REFERENCES "Event"("id") ON DELETE CASCADE, "title" TEXT, "content" TEXT NOT NULL, "sourceType" "SourceType" NOT NULL, "metadata" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "Conversation" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "clientId" UUID NOT NULL, "eventId" UUID NOT NULL REFERENCES "Event"("id") ON DELETE CASCADE, "userId" UUID REFERENCES "User"("id") ON DELETE SET NULL, "guestId" UUID REFERENCES "Guest"("id") ON DELETE SET NULL, "type" "ConversationType" NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "ConversationMessage" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "conversationId" UUID NOT NULL REFERENCES "Conversation"("id") ON DELETE CASCADE, "role" "MessageRole" NOT NULL, "content" TEXT NOT NULL, "status" "MessageStatus" NOT NULL DEFAULT 'COMPLETE', "metadata" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "actorUserId" UUID REFERENCES "User"("id") ON DELETE SET NULL, "clientId" UUID REFERENCES "Client"("id") ON DELETE SET NULL, "eventId" UUID REFERENCES "Event"("id") ON DELETE SET NULL, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT, "requestId" TEXT NOT NULL, "metadata" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "OutboxEvent" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "clientId" UUID REFERENCES "Client"("id") ON DELETE CASCADE, "eventId" UUID REFERENCES "Event"("id") ON DELETE CASCADE, "type" TEXT NOT NULL, "aggregateId" TEXT NOT NULL, "payload" JSONB NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "availableAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "processedAt" TIMESTAMPTZ(3), "lastError" TEXT, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "BackgroundJob" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "clientId" UUID REFERENCES "Client"("id") ON DELETE CASCADE, "eventId" UUID REFERENCES "Event"("id") ON DELETE CASCADE, "type" TEXT NOT NULL, "idempotencyKey" TEXT NOT NULL UNIQUE, "payload" JSONB NOT NULL, "status" "JobStatus" NOT NULL DEFAULT 'PENDING', "progress" INTEGER NOT NULL DEFAULT 0, "attempts" INTEGER NOT NULL DEFAULT 0, "maxAttempts" INTEGER NOT NULL DEFAULT 5, "availableAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lockedAt" TIMESTAMPTZ(3), "lockedBy" TEXT, "lastError" TEXT, "completedAt" TIMESTAMPTZ(3), "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL);

CREATE INDEX "ClientMembership_clientId_status_idx" ON "ClientMembership"("clientId", "status");
CREATE INDEX "Event_clientId_status_idx" ON "Event"("clientId", "status");
CREATE INDEX "Event_clientId_startAt_idx" ON "Event"("clientId", "startAt");
CREATE INDEX "EventFact_eventId_sourceType_idx" ON "EventFact"("eventId", "sourceType");
CREATE INDEX "EventLocation_eventId_idx" ON "EventLocation"("eventId");
CREATE INDEX "EventContact_eventId_idx" ON "EventContact"("eventId");
CREATE INDEX "ScheduleItem_eventId_startAt_idx" ON "ScheduleItem"("eventId", "startAt");
CREATE INDEX "Guest_eventId_fullName_idx" ON "Guest"("eventId", "fullName");
CREATE INDEX "Invitation_eventId_status_idx" ON "Invitation"("eventId", "status");
CREATE INDEX "GuestSession_eventId_guestId_idx" ON "GuestSession"("eventId", "guestId");
CREATE INDEX "Document_eventId_processingStatus_idx" ON "Document"("eventId", "processingStatus");
CREATE INDEX "Document_clientId_eventId_idx" ON "Document"("clientId", "eventId");
CREATE INDEX "DocumentChunk_eventId_idx" ON "DocumentChunk"("eventId");
CREATE INDEX "DocumentChunk_clientId_eventId_idx" ON "DocumentChunk"("clientId", "eventId");
CREATE INDEX "KnowledgeEntry_clientId_eventId_idx" ON "KnowledgeEntry"("clientId", "eventId");
CREATE INDEX "Conversation_eventId_createdAt_idx" ON "Conversation"("eventId", "createdAt");
CREATE INDEX "AuditLog_clientId_createdAt_idx" ON "AuditLog"("clientId", "createdAt");
CREATE INDEX "AuditLog_eventId_createdAt_idx" ON "AuditLog"("eventId", "createdAt");
CREATE INDEX "OutboxEvent_processedAt_availableAt_idx" ON "OutboxEvent"("processedAt", "availableAt");
CREATE INDEX "BackgroundJob_status_availableAt_idx" ON "BackgroundJob"("status", "availableAt");
CREATE INDEX "BackgroundJob_eventId_status_idx" ON "BackgroundJob"("eventId", "status");
CREATE INDEX "DocumentChunk_embedding_hnsw_idx" ON "DocumentChunk" USING hnsw ("embedding" vector_cosine_ops);
